CREATE TABLE `areas_brutas_avaliacoes` (
  `id` int NOT NULL AUTO_INCREMENT,
  `area_bruta_id` int NOT NULL,
  `ano` int NOT NULL,
  `valor_mercado` decimal(18,4) DEFAULT NULL,
  `valor_subsidiado` decimal(18,4) DEFAULT NULL,
